package main

import (
	"context"
	"log"
	"os"

	"github.com/juhokoskela/pipedrive-go/pipedrive"
	v1 "github.com/juhokoskela/pipedrive-go/pipedrive/v1"
)

func main() {
	client, err := v1.NewClient(pipedrive.Config{Auth: pipedrive.APITokenAuth("token")})
	if err != nil {
		log.Fatal(err)
	}

	f, err := os.Open("contract.pdf")
	if err != nil {
		log.Fatal(err)
	}
	defer f.Close()

	file, err := client.Files.Upload(
		context.Background(),
		"contract.pdf",
		f,
		v1.WithFileDealID(v1.DealID(42)),
	)
	if err != nil {
		log.Fatal(err)
	}
	log.Printf("uploaded file id=%d", file.ID)
}
